from django.db.models import Sum


def backfill_statuses(apps, schema_editor):
    PurchaseOrder = apps.get_model("accounts", "PurchaseOrder")
    PurchaseOrderItem = apps.get_model("accounts", "PurchaseOrderItem")
    MaterialReceive = apps.get_model("accounts", "MaterialReceive")
    MaterialReceiveItem = apps.get_model("accounts", "MaterialReceiveItem")

    # Existing GRNs already affected Product.stock before status tracking existed.
    MaterialReceive.objects.update(status="verified")

    ordered_by_po = {}
    for row in PurchaseOrderItem.objects.values("purchase_order_id", "product_id").annotate(qty=Sum("quantity")):
        ordered_by_po.setdefault(row["purchase_order_id"], {})[row["product_id"]] = row["qty"] or 0

    received_by_po = {}
    for row in MaterialReceiveItem.objects.values("material_receive__purchase_order_id", "product_id").annotate(qty=Sum("quantity")):
        po_id = row["material_receive__purchase_order_id"]
        received_by_po.setdefault(po_id, {})[row["product_id"]] = row["qty"] or 0

    to_update = []
    for po in PurchaseOrder.objects.all():
        ord_map = ordered_by_po.get(po.id, {})
        rec_map = received_by_po.get(po.id, {})

        if ord_map and all(rec_map.get(pid, 0) >= qty for pid, qty in ord_map.items()):
            new_status = "received"
        elif sum(rec_map.values()) > 0:
            new_status = "partially_received"
        elif ord_map:
            new_status = "sent"
        else:
            new_status = "draft"

        if po.status != new_status:
            po.status = new_status
            to_update.append(po)

    if to_update:
        PurchaseOrder.objects.bulk_update(to_update, ["status"])


